import 'package:flutter/foundation.dart';
import 'governance_models.dart';import 'governance_repository.dart';
enum GovernancePhase{initial,loading,ready,empty,error,offline}
class GovernanceController extends ChangeNotifier {GovernanceController(this.repository);final GovernanceRepository repository;GovernancePhase phase=GovernancePhase.initial;GovernanceSnapshot? snapshot;String? message;bool mutating=false;Future<void> load()async{phase=GovernancePhase.loading;message=null;notifyListeners();try{snapshot=await repository.load();phase=GovernancePhase.ready;}on GovernanceOfflineException catch(e){phase=GovernancePhase.offline;message=e.message;}catch(e){phase=GovernancePhase.error;message=e.toString();}notifyListeners();}Future<void> baseline(String name)=>_act(()=>repository.createBaselinePolicy(name));Future<void> setPolicyActive(String id,{required bool active})=>_act(()=>repository.setPolicyActive(id,active:active));Future<void> install(String id)=>_act(()=>repository.installPackage(id));Future<void> uninstall(String id)=>_act(()=>repository.uninstallPackage(id));Future<void> updateTarget(RoutingTarget value)=>_act(()=>repository.updateTarget(value));Future<void> exportAudit(String format)=>_act(()=>repository.exportAudit(format),reload:false);Future<void> _act(Future<Object?> Function() action,{bool reload=true})async{mutating=true;notifyListeners();try{await action();if(reload)await load();}catch(e){message=e.toString();phase=GovernancePhase.error;}finally{mutating=false;notifyListeners();}}}
